[
  {
    "statement": "Providing bat boxes appears to be the most promising cost-effective method for increasing bat populations in agricultural landscapes.",
    "citations": []
  },
  {
    "statement": "Bats successfully use bat boxes installed in farmland and related habitats.",
    "citations": []
  },
  {
    "statement": "Studies demonstrate that bats occupy bat boxes in farmland and related environments.",
    "citations": []
  },
  {
    "statement": "Installation of bat boxes in farm forestry sites showed higher occupancy rates compared to native forest locations.",
    "citations": []
  },
  {
    "statement": "The effectiveness of bat boxes in agricultural settings is indicated by higher occupancy rates in farm forestry sites.",
    "citations": []
  },
  {
    "statement": "The number of bats using bat boxes increased by 2–10 times within 10 years after installation.",
    "citations": []
  },
  {
    "statement": "Installing bat boxes provides measurable population benefits for bats.",
    "citations": []
  },
  {
    "statement": "Agri-environment schemes involving farmer engagement have shown mixed results.",
    "citations": []
  },
  {
    "statement": "Bat boxes offer a more direct and proven approach to increasing bat populations.",
    "citations": []
  },
  {
    "statement": "72 bat species have used bat boxes worldwide.",
    "citations": []
  },
  {
    "statement": "Different bat box designs can be selected based on local bat species requirements.",
    "citations": []
  }
]

[
  {
    "statement": "There are no available studies that have evaluated the effects of releasing captive-bred bats into the wild on bat populations.",
    "citations": []
  },
  {
    "statement": "Eight studies have examined breeding bats in captivity.",
    "citations": []
  },
  {
    "statement": "Studies have shown that 6-100% of female bats captured in the wild successfully conceived, gave birth and reared young in captivity.",
    "citations": []
  },
  {
    "statement": "Studies have shown that 20-100% of bat pups born in captivity survived from between 10 days to adulthood.",
    "citations": []
  },
  {
    "statement": "One study regarding the rehabilitation and release of injured or orphaned bats found that 70-90% of hand-reared pipistrelle bats survived for at least 4-14 days after release.",
    "citations": []
  },
  {
    "statement": "One study found that 13% of ringed hand-reared pipistrelle bats were found alive in bat boxes 38 days to almost four years after release.",
    "citations": []
  },
  {
    "statement": "No data is available specifically on the long-term success rates of releasing captive-bred bats into the wild.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence indicates that bat boxes are the most widely used and practical cost-effective method for creating artificial bat roosts.",
    "citations": []
  },
  {
    "statement": "Forty-four studies evaluated bat box effectiveness across Europe, North America, Australia, and South America.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Seventy-two bat species have been found using bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Only 18 bat species commonly used bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Studies found bats occupied between 0% and 100% of provided bat boxes.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Optimal design factors for bat boxes include black coloration and a larger size.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Concrete is a more optimal construction material for bat boxes than wood.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Proper placement for bat boxes is on buildings rather than on trees.",
    "citations": [
      "1024"
    ]
  },
  {
    "statement": "Information regarding bat boxes, bat grilles, and roost improvements was covered, but no specific cost data was captured.",
    "citations": [
