    ]
  },
  {
    "statement": "Artificial caves and hibernacula were used by up to four bat species in UK and German studies.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "Alternative roosts within developments had variable success rates, with occupancy at development sites ranging from 13% to 74%.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "The simpler bat box approach appears to be the most cost-effective.",
    "citations": []
  },
  {
    "statement": "The bat box approach has an extensive evidence base and higher success rates compared to more elaborate artificial cave systems.",
    "citations": []
  }
]
